"""SOLUTION:"""
import json
import itertools

# Helper functions for time parsing/formatting
def parse_time(tstr):
    # tstr like '9:00' or '13:30'
    h, m = map(int, tstr.split(':'))
    return h * 60 + m

def minutes_to_str(m):
    h = m // 60
    mm = m % 60
    return f"{h}:{mm:02d}"

# Input variables (meeting constraints and travel times)
start_location = "North Beach"
arrival_time_str = "9:00"

travel = {
    "North Beach": {"Pacific Heights": 8, "Embarcadero": 6},
    "Pacific Heights": {"North Beach": 9, "Embarcadero": 10},
    "Embarcadero": {"North Beach": 5, "Pacific Heights": 11},
}
# ensure self travel times
for a in list(travel.keys()):
    travel[a][a] = 0

def ttime(a, b):
    return travel[a][b]

people = [
    {
        "name": "Karen",
        "location": "Pacific Heights",
        "win_start": parse_time("18:45"),
        "win_end": parse_time("20:15"),
        "min_dur": 90
    },
    {
        "name": "Mark",
        "location": "Embarcadero",
        "win_start": parse_time("13:00"),
        "win_end": parse_time("17:45"),
        "min_dur": 120
    }
]

start_time = parse_time(arrival_time_str)

# Objective: maximize (number of people met, total meeting minutes)
best_solution = {
    "score": (-1, -1),  # (num_met, total_minutes)
    "itinerary": []
}

def compare_scores(s1, s2):
    # returns True if s1 better than s2
    if s1[0] != s2[0]:
        return s1[0] > s2[0]
    if s1[1] != s2[1]:
        return s1[1] > s2[1]
    return False

def dfs(order, idx, curr_loc, curr_time, itinerary, total_minutes):
    global best_solution
    if idx == len(order):
        score = (len(itinerary), total_minutes)
        if compare_scores(score, best_solution["score"]):
            best_solution = {
                "score": score,
                "itinerary": list(itinerary)
            }
        return

    person = order[idx]
    travel_minutes = ttime(curr_loc, person["location"])
    arrival = curr_time + travel_minutes

    earliest_start = max(arrival, person["win_start"])
    latest_start = person["win_end"] - person["min_dur"]

    if earliest_start > latest_start:
        return

    # Optimization: if the person's window equals min duration, only one option
    if person["win_end"] - person["win_start"] == person["min_dur"]:
        s_candidates = [max(earliest_start, person["win_start"])]
    else:
        s_candidates = range(earliest_start, latest_start + 1)

    for s in s_candidates:
        d_min = person["min_dur"]
        d_max = person["win_end"] - s
        # Iterate durations from longest to shortest to find better schedules earlier
        for d in range(d_max, d_min - 1, -1):
            e = s + d
            # Add this meeting
            itinerary.append({
                "action": "meet",
                "location": person["location"],
                "person": person["name"],
                "start_time": minutes_to_str(s),
                "end_time": minutes_to_str(e)
            })
            dfs(order, idx + 1, person["location"], e, itinerary, total_minutes + d)
            itinerary.pop()

# Explore all subsets and permutations of people, maximizing number met first
n = len(people)
for r in range(n, -1, -1):
    for subset in itertools.combinations(people, r):
        if r == 0:
            # Consider empty schedule as fallback
            score = (0, 0)
            if compare_scores(score, best_solution["score"]):
                best_solution = {"score": score, "itinerary": []}
            continue
        for order in itertools.permutations(subset):
            dfs(order, 0, start_location, start_time, [], 0)

# Sort itinerary by start time to ensure chronological order in output
def time_key(item):
    return parse_time(item["start_time"])

final_itinerary = sorted(best_solution["itinerary"], key=time_key)

output = {
    "itinerary": final_itinerary
}

print(json.dumps(output, ensure_ascii=False))
